(()=>{
'use strict';
const $=id=>document.getElementById(id),D=window.JK_PHASE30_DATA,U=window.JK_PHASE31_DATA,R=window.JK_PHASE32_DATA,A=window.JK_PHASE33_DATA,C=window.JK_PHASE34_DATA,S=window.JK_PHASE35_DATA;
let result={},lastImport=null,manualDecisions=[],cutoverImport=null,cutoverLocks=[],cutoverExecutions=[],smokeRuns=[],observations=[],incidents=[],rollbacks=[];
const badge=s=>`<span class="status ${s}">${s}</span>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const unwrap=row=>row?.payload&&typeof row.payload==='object'?row.payload:row;
function gateRows(){const s=D.state.gates;const rows=[['내비게이션·권한',s.navigation],['접근성 정적 계약',s.accessibilityStatic],['화면낭독기 실기기',R.state.gates.assistiveTechnology],['성능 계측 기반',s.performanceInstrumentation],['실기기 성능',R.state.gates.performanceDevice],['PWA 합성 회귀',s.pwaSynthetic],['외부 설치',R.state.gates.pwaExternalInstall],['학습 불변조건',R.state.gates.learningRegression],['리허설 패키지',R.state.gates.rehearsalPackage]];$('gates').innerHTML=rows.map(([a,b])=>`<div class="check"><strong>${a}</strong>${badge(b)}</div>`).join('')}
function externalRows(){const rows=[['외부 도메인·TLS',R.state.gates.deployment],['물리 기기·펜 QA',R.state.gates.deviceQa],['운영 복원 훈련',R.state.gates.recoveryDrill],['실제 7일 기준선',R.state.baseline]];$('external').innerHTML=rows.map(([a,b])=>`<div class="check"><strong>${a}</strong>${badge(b)}</div>`).join('')}
function perfRows(){const samples=JK_RC.performanceSamples().slice(-30).reverse(),evald=JK_RC.evaluatePerformance(samples,D.performance.budgets);$('samples').textContent=samples.length;$('perfRows').innerHTML=evald.rows.map(r=>`<tr><td>${new Date(r.at).toLocaleString()}</td><td>${r.page||'-'}</td><td>${r.metric}</td><td>${r.durationMs}ms</td><td>${Number.isFinite(r.budgetMs)?r.budgetMs+'ms':'-'}</td><td>${badge(r.status)}</td></tr>`).join('')||'<tr><td colspan="6">아직 이 기기의 런타임 표본이 없습니다.</td></tr>';return evald}
function renderFoundation(){const navAudit=JK_RC.navigationAudit(D.navigation),perf=perfRows(),journey=JK_PHASE31.journeyAudit(U.policy),responsive=JK_PHASE31.responsiveAudit(U.policy),devicePlan=JK_PHASE32.auditDevicePlan(R.devicePlan);$('candidateStatus').textContent=C.state.status;$('candidateStatus').className='status '+C.state.status;$('freeze').textContent=C.state.featureFreeze;$('pages').textContent=`${D.navigation.pages.length}개`;$('blockers').textContent=lastImport?.finalEvaluation?.blockers?.releaseBlocking??R.state.openBlockers;gateRows();externalRows();$('exceptions').innerHTML=D.policy.freezeExceptions.map(x=>`<div class="check"><strong>${x}</strong><span>수정 허용</span></div>`).join('');$('navRows').innerHTML=D.navigation.pages.map(p=>`<tr><td>${p.page}</td><td>${p.role}</td><td>${p.auth}</td><td>${p.label}</td></tr>`).join('');$('journeySteps').textContent=Math.max(...Object.values(U.policy.journeys).map(x=>x.maxSteps))+'단계';$('messageCount').textContent=Object.keys(U.policy.messageCatalog).length+'개';$('responsiveSynthetic').textContent=responsive.pass?'PASS':'FAIL';$('responsiveManual').textContent=R.state.gates.deviceQa;$('rehearsalPackage').textContent=R.state.gates.rehearsalPackage;$('deviceBatches').textContent=devicePlan.profiles.length+'개';$('evidenceRule').textContent=devicePlan.pass?'PASS':'FAIL';$('productionApproval').textContent=lastImport?.finalEvaluation?.status||A.state.productionApproval;result={generatedAt:new Date().toISOString(),version:'35.0',navigationAudit:navAudit,journey,responsive,devicePlan,performance:perf,state:C.state,policy:C.policy,phase33State:A.state,phase33Policy:A.policy,phase32State:R.state,phase31State:U.state,phase30State:D.state,phase35State:S?.state,phase35Policy:S?.policy}}
function downloadJson(payload,name){const b=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function downloadStatus(){downloadJson(result,'JK_ENG_RC2_PHASE35_STATUS.json')}
function hex(buffer){return [...new Uint8Array(buffer)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function hashFile(file){return hex(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))}
async function readJsonFile(file){const raw=await file.text();return JSON.parse(raw)}
async function catalogFiles(files){const rows=[];for(const file of files){rows.push({name:file.name,path:file.webkitRelativePath||file.name,size:file.size,type:file.type,lastModified:file.lastModified,sha256:await hashFile(file),source:'selected-file'})}return rows}
function renderApproval(){const v=lastImport?.evidenceVerification,e=lastImport?.finalEvaluation,latest=manualDecisions[0];let top=latest?.accepted?latest.action:(e?.status||'NOT_IMPORTED');$('finalApprovalBadge').textContent=top;$('finalApprovalBadge').className=`status ${top}`;$('approvalPackageStatus').textContent=v?.packageIdentityPass?'PASS':'NOT_IMPORTED';$('approvalFileCount').textContent=v?.catalog?.length||0;$('approvalIntegrity').textContent=v?.status||'NOT_RUN';$('approvalReadiness').textContent=e?.status||'BLOCKED';$('exportApprovalAudit').disabled=!lastImport;
 if(!lastImport){$('approvalImportMessage').textContent='외부 증거가 없으므로 승인 불가 상태입니다.';$('approvalIssues').innerHTML='<div class="issue error">EXTERNAL_EVIDENCE_REQUIRED · 실제 증거 패키지와 파일을 가져와야 합니다.</div>';$('approvalGateRows').innerHTML='<tr><td colspan="4">가져온 증거 패키지가 없습니다.</td></tr>'}
 else{
  $('approvalImportMessage').textContent=`검증 ${new Date(v.verifiedAt).toLocaleString()} · 패키지 ${esc(lastImport.sourcePackageMeta?.name||'-')}`;
  const issues=[...(v.errors||[]).map(x=>({...x,kind:'error'})),...(v.warnings||[]).map(x=>({...x,kind:'warning'})),...((e.reasons||[]).map(id=>({id,detail:'최종 승인 조건 미충족',kind:'error'})))];$('approvalIssues').innerHTML=issues.map(x=>`<div class="issue ${x.kind}"><strong>${esc(x.id)}</strong>${x.detail?` · ${esc(x.detail)}`:''}</div>`).join('')||'<div class="issue">검증 오류와 경고가 없습니다.</div>';
  $('approvalGateRows').innerHTML=(e.gates||[]).map(g=>`<tr><td>${esc(g.label)}</td><td>${badge(g.sourceStatus)}</td><td>${g.evidenceCount}개${g.missingEvidence?.length?`<br><small>누락: ${esc(g.missingEvidence.join(', '))}</small>`:''}</td><td>${badge(g.status)}</td></tr>`).join('');
 }
 $('approvalDecisionHistory').innerHTML=manualDecisions.map(d=>`<div class="decisionRow"><div><strong>${esc(d.action)} · ${esc(d.reviewer)}</strong><div class="note">${esc(d.reason)}<br>${new Date(d.decidedAt).toLocaleString()}</div></div>${badge(d.accepted?'RECORDED':'REJECTED_RECORD')}</div>`).join('')||'<div class="note">수동 결정 기록이 없습니다.</div>';
}
async function loadApprovalAudit(){const rows=await JK_STORAGE.listApprovalAudit();lastImport=rows.filter(x=>x.type==='phase33_evidence_import_saved').map(unwrap)[0]||null;manualDecisions=rows.filter(x=>x.type==='phase33_release_decision_saved').map(unwrap);renderApproval()}
async function importAndVerify(){const packageFile=$('approvalPackageFile').files?.[0],files=[...($('approvalEvidenceFiles').files||[])],catalogFile=$('approvalCatalogFile').files?.[0];if(!packageFile){$('approvalImportMessage').textContent='Phase 32 증거 패키지 JSON을 선택해야 합니다.';return}
 $('approvalImportMessage').textContent='파일 SHA-256을 계산하고 있습니다.';try{const pkg=await readJsonFile(packageFile),catalog=await catalogFiles(files),expectedCatalog=catalogFile?JK_PHASE33.parseCatalogText(await catalogFile.text()):[];const sourcePackageMeta={name:packageFile.name,size:packageFile.size,lastModified:packageFile.lastModified,sha256:await hashFile(packageFile)};const evidenceVerification=JK_PHASE33.verifyEvidencePackage(pkg,catalog,{expectedCatalog});const finalEvaluation=JK_PHASE33.evaluateFinalApproval(pkg,evidenceVerification);const record={format:'JK_ENG_PHASE33_EVIDENCE_IMPORT_RECORD',version:'33.0',importId:evidenceVerification.verificationId,sourcePackage:pkg,sourcePackageMeta,evidenceVerification,finalEvaluation,importedAt:new Date().toISOString()};await JK_STORAGE.appendApprovalAudit({type:'phase33_evidence_import_saved',entityId:record.importId,payload:record});await loadApprovalAudit();renderFoundation()}catch(error){console.error(error);$('approvalImportMessage').textContent=`가져오기 실패: ${error.message||error}`}}
async function saveDecision(){if(!lastImport){$('approvalDecisionMessage').textContent='먼저 증거 패키지를 가져와 검증해야 합니다.';return}const decision=JK_PHASE33.makeManualDecision({action:$('approvalDecision').value,reviewer:$('approvalReviewer').value,reason:$('approvalReason').value,verificationId:lastImport.evidenceVerification?.verificationId},lastImport.finalEvaluation);if(!decision.accepted){$('approvalDecisionMessage').textContent=`기록 불가: ${decision.errors.join(', ')}`;return}await JK_STORAGE.appendApprovalAudit({type:'phase33_release_decision_saved',entityId:decision.decisionId,payload:decision});$('approvalDecisionMessage').textContent=`${decision.action} 결정을 감사기록에 저장했습니다.`;$('approvalReason').value='';await loadApprovalAudit();renderFoundation()}
function exportAudit(){if(!lastImport)return;const bundle=JK_PHASE33.buildAuditBundle({sourcePackage:lastImport.sourcePackage,sourcePackageMeta:lastImport.sourcePackageMeta,evidenceVerification:lastImport.evidenceVerification,finalEvaluation:lastImport.finalEvaluation,manualDecisions});downloadJson(bundle,`JK_ENG_RC2_Phase33_Audit_${new Date().toISOString().slice(0,10)}.json`)}

function ensureSmokeInputs(){if($('cutoverSmokeRows').children.length)return;const defs=C.policy.smokeTests||[];$('cutoverSmokeRows').innerHTML=defs.map(d=>`<div class="smokeRow"><strong>${esc(d.label)}</strong><select id="smokeStatus_${d.id}"><option>NOT_RUN</option><option>PASS</option><option>FAIL</option></select><input id="smokeEvidence_${d.id}" placeholder="증거 파일명·로그 참조"></div>`).join('')}
function latestObservationEvaluation(){const obs=observations[0];return obs?JK_PHASE34.evaluateObservation(obs,incidents):JK_PHASE34.evaluateObservation({},incidents)}
function renderCutover(){ensureSmokeInputs();const verification=cutoverImport?.predeployVerification,lock=cutoverLocks[0],execution=cutoverExecutions[0],smoke=smokeRuns[0],obs=observations[0],obsEval=latestObservationEvaluation(),rollback=rollbacks[0];const top=rollback?.accepted?'ROLLBACK_REQUESTED':obsEval.status==='ROLLBACK_REQUIRED'?'ROLLBACK_REQUIRED':obsEval.status==='OBSERVATION_COMPLETE'?'OBSERVATION_COMPLETE':obs?.status==='OBSERVING'?'OBSERVING':execution?.status||'CUTOVER_NOT_RUN';$('cutoverBadge').textContent=top;$('cutoverBadge').className=`status ${top}`;$('cutoverBundleStatus').textContent=verification?.status==='PASS'?'PASS':'NOT_IMPORTED';$('cutoverShaStatus').textContent=verification?.status==='PASS'?'PASS':verification?'FAIL':'NOT_RUN';$('cutoverLockStatus').textContent=lock?.status||'UNLOCKED';$('cutoverExecutionStatus').textContent=execution?.status||'CUTOVER_NOT_RUN';$('smokeBadge').textContent=smoke?.status||'SMOKE_NOT_RUN';$('smokeBadge').className=`status ${smoke?.status||'SMOKE_NOT_RUN'}`;$('observationBadge').textContent=obsEval.status;$('observationBadge').className=`status ${obsEval.status}`;$('exportCutoverAudit').disabled=!cutoverImport;$('requestImmediateRollback').disabled=obsEval.rollbackDecision!=='ROLLBACK_REQUIRED';$('observationWindow').textContent=obs?.startedAt?`시작 ${new Date(obs.startedAt).toLocaleString()} · 종료 예정 ${new Date(obs.endsAt).toLocaleString()} · P0/P1 미해결 ${obsEval.openP0P1}건`:'스모크 PASS 이후 관측을 시작합니다.';$('incidentRows').innerHTML=incidents.map(i=>`<tr><td>${new Date(i.at).toLocaleString()}</td><td>${badge(i.severity)}</td><td>${badge(i.status)}</td><td><strong>${esc(i.title||'-')}</strong><br><small>${esc(i.detail||'')}${i.evidence?` · ${esc(i.evidence)}`:''}</small></td></tr>`).join('')||'<tr><td colspan="4">관측 기록이 없습니다.</td></tr>';if(cutoverImport)$('cutoverImportMessage').textContent=`승인 번들 ${esc(cutoverImport.approvedBundleMeta?.name||'-')} · SHA-256 ${verification?.bundleSha256?.slice(0,16)||'-'}… · ${verification?.status||'-'}`;if(lock)$('cutoverLockMessage').textContent=`${lock.status} · ${new Date(lock.lockedAt).toLocaleString()}`;if(execution)$('cutoverExecutionMessage').textContent=`${execution.status} · ${execution.targetUrl||'-'} · ${new Date(execution.executedAt).toLocaleString()}`;if(smoke)$('smokeMessage').textContent=`${smoke.status} · ${new Date(smoke.testedAt||Date.now()).toLocaleString()}`;if(rollback)$('rollbackMessage').textContent=`${rollback.status} · 외부 서버 롤백 실행 여부는 ${rollback.externalRollbackExecution}.`}
async function loadCutoverAudit(){const rows=await JK_STORAGE.listApprovalAudit();cutoverImport=rows.filter(x=>x.type==='phase34_cutover_bundle_import_saved').map(unwrap)[0]||null;cutoverLocks=rows.filter(x=>x.type==='phase34_cutover_lock_saved').map(unwrap);cutoverExecutions=rows.filter(x=>x.type==='phase34_cutover_execution_saved').map(unwrap);smokeRuns=rows.filter(x=>x.type==='phase34_smoke_run_saved').map(unwrap);observations=rows.filter(x=>x.type==='phase34_observation_saved').map(unwrap);incidents=rows.filter(x=>x.type==='phase34_incident_saved').map(unwrap);rollbacks=rows.filter(x=>x.type==='phase34_rollback_saved').map(unwrap);renderCutover()}
async function verifyCutoverBundle(){const file=$('cutoverAuditBundleFile').files?.[0],expected=$('cutoverExpectedSha').value;if(!file){$('cutoverImportMessage').textContent='Phase 33 승인 감사 번들 JSON을 선택해야 합니다.';return}$('cutoverImportMessage').textContent='승인 번들의 SHA-256과 승인 결정을 재검증하고 있습니다.';try{const raw=await file.text(),bundle=JSON.parse(raw),computedSha256=await hashFile(file),predeployVerification=JK_PHASE34.verifyApprovedAuditBundle(bundle,{computedSha256,expectedSha256:expected}),approvedBundleMeta={name:file.name,size:file.size,lastModified:file.lastModified,sha256:computedSha256,expectedSha256:JK_PHASE34.normalizeHash(expected)};const record={format:'JK_ENG_PHASE34_CUTOVER_BUNDLE_IMPORT',version:'34.0',importId:predeployVerification.verificationId,approvedBundle:bundle,approvedBundleMeta,predeployVerification,importedAt:new Date().toISOString()};await JK_STORAGE.appendApprovalAudit({type:'phase34_cutover_bundle_import_saved',entityId:record.importId,payload:record});await loadCutoverAudit();$('cutoverImportMessage').textContent=predeployVerification.status==='PASS'?'승인 번들 재검증 PASS. 실행 잠금을 생성할 수 있습니다.':`재검증 FAIL: ${predeployVerification.errors.map(x=>x.id).join(', ')}`}catch(error){console.error(error);$('cutoverImportMessage').textContent=`승인 번들 재검증 실패: ${error.message||error}`}}
async function createExecutionLock(){if(!cutoverImport){$('cutoverLockMessage').textContent='먼저 승인 번들을 재검증해야 합니다.';return}const file=$('cutoverAuditBundleFile').files?.[0];if(!file){$('cutoverLockMessage').textContent='잠금 직전 재해시를 위해 동일한 승인 번들 파일을 다시 선택해야 합니다.';return}const computedSha256=await hashFile(file),expectedSha256=cutoverImport.approvedBundleMeta?.expectedSha256||$('cutoverExpectedSha').value,verification=JK_PHASE34.verifyApprovedAuditBundle(cutoverImport.approvedBundle,{computedSha256,expectedSha256});const checklist={singleLearnerScope:$('cutoverCheckSingle').checked,rollbackTargetReady:$('cutoverCheckRollback').checked,adminRecoveryReady:$('cutoverCheckAdmin').checked,backupSnapshotReady:$('cutoverCheckBackup').checked,externalUrlConfirmed:$('cutoverCheckUrl').checked},lock=JK_PHASE34.createCutoverLock({checklist,operator:$('cutoverOperator').value,reason:$('cutoverLockReason').value},verification);if(!lock.accepted){$('cutoverLockMessage').textContent=`잠금 불가: ${lock.errors.join(', ')}`;return}await JK_STORAGE.appendApprovalAudit({type:'phase34_cutover_lock_saved',entityId:lock.lockId,payload:lock});await loadCutoverAudit()}
async function recordCutoverExecution(){const lock=cutoverLocks[0],file=$('cutoverAuditBundleFile').files?.[0];if(!lock){$('cutoverExecutionMessage').textContent='실행 잠금이 필요합니다.';return}if(!file){$('cutoverExecutionMessage').textContent='실행 직전 SHA-256 재확인을 위해 동일한 승인 번들 파일을 선택해야 합니다.';return}const reverifiedSha256=await hashFile(file),execution=JK_PHASE34.createCutoverExecution({targetUrl:$('cutoverTargetUrl').value,actualExternalContext:$('cutoverActualExternal').checked,confirmationPhrase:$('cutoverConfirmPhrase').value,reverifiedSha256,operator:$('cutoverOperator').value},lock);if(!execution.accepted){$('cutoverExecutionMessage').textContent=`실행 기록 불가: ${execution.errors.join(', ')}`;return}await JK_STORAGE.appendApprovalAudit({type:'phase34_cutover_execution_saved',entityId:execution.executionId,payload:execution});await loadCutoverAudit();renderFoundation()}
async function recordSmokeRun(){const execution=cutoverExecutions[0],tests={};for(const def of C.policy.smokeTests||[])tests[def.id]={status:$(`smokeStatus_${def.id}`).value,evidence:$(`smokeEvidence_${def.id}`).value};const run=JK_PHASE34.evaluateSmokeRun({actualExternalContext:$('smokeActualExternal').checked,operator:$('cutoverOperator').value,tests},execution||{});await JK_STORAGE.appendApprovalAudit({type:'phase34_smoke_run_saved',entityId:run.runId,payload:run});await loadCutoverAudit()}
async function startObservationWindow(){const obs=JK_PHASE34.startObservation({operator:$('cutoverOperator').value},cutoverExecutions[0]||{},smokeRuns[0]||{});if(obs.status!=='OBSERVING'){$('observationWindow').textContent=`관측 시작 불가: ${(obs.errors||[]).join(', ')}`;return}await JK_STORAGE.appendApprovalAudit({type:'phase34_observation_saved',entityId:obs.observationId,payload:obs});await loadCutoverAudit()}
async function recordObservationIncident(){if(!observations[0]||observations[0].status!=='OBSERVING'){$('rollbackMessage').textContent='24시간 관측을 먼저 시작해야 합니다.';return}const incident=JK_PHASE34.normalizeIncident({severity:$('incidentSeverity').value,title:$('incidentTitle').value,detail:$('incidentDetail').value,evidence:$('incidentEvidence').value});if(!incident.title){$('rollbackMessage').textContent='사고 제목을 입력해야 합니다.';return}await JK_STORAGE.appendApprovalAudit({type:'phase34_incident_saved',entityId:incident.incidentId,payload:incident});$('incidentTitle').value='';$('incidentDetail').value='';$('incidentEvidence').value='';await loadCutoverAudit()}
async function requestImmediateRollback(){const evaluation=latestObservationEvaluation(),record=JK_PHASE34.createRollbackRecord({operator:$('cutoverOperator').value,reason:$('rollbackReason').value,confirmationPhrase:$('rollbackConfirmPhrase').value},evaluation);if(!record.accepted){$('rollbackMessage').textContent=`롤백 요청 불가: ${record.errors.join(', ')}`;return}JK_RC.requestRollback();await JK_STORAGE.appendApprovalAudit({type:'phase34_rollback_saved',entityId:record.rollbackId,payload:record});$('rollbackMessage').textContent='이전 PWA 캐시 전환과 운영 롤백 요청을 기록했습니다. 외부 서버 롤백은 별도 실행·검증이 필요합니다.';await loadCutoverAudit()}
function exportCutoverAudit(){if(!cutoverImport)return;const bundle=JK_PHASE34.buildCutoverAuditBundle({approvedBundleMeta:cutoverImport.approvedBundleMeta,predeployVerification:cutoverImport.predeployVerification,cutoverLocks,executions:cutoverExecutions,smokeRuns,observations,incidents,rollbacks});downloadJson(bundle,`JK_ENG_RC2_Phase34_Cutover_Audit_${new Date().toISOString().slice(0,10)}.json`)}

async function boot(){await JK_AUTH.requireRole('admin');await JK_STORAGE.init();await loadApprovalAudit();await loadCutoverAudit();renderFoundation();$('refresh').onclick=()=>{renderFoundation();renderApproval();renderCutover()};$('export').onclick=downloadStatus;$('validateApprovalEvidence').onclick=importAndVerify;$('saveApprovalDecision').onclick=saveDecision;$('exportApprovalAudit').onclick=exportAudit;$('verifyCutoverBundle').onclick=verifyCutoverBundle;$('createCutoverLock').onclick=createExecutionLock;$('recordCutoverExecution').onclick=recordCutoverExecution;$('recordSmokeRun').onclick=recordSmokeRun;$('startObservation').onclick=startObservationWindow;$('recordIncident').onclick=recordObservationIncident;$('requestImmediateRollback').onclick=requestImmediateRollback;$('exportCutoverAudit').onclick=exportCutoverAudit;$('rollback').onclick=()=>{JK_RC.requestRollback();$('pwaMessage').textContent='이전 캐시 전환을 요청했습니다. 결과는 서비스워커 응답으로 확인합니다.'};$('restore').onclick=()=>{JK_RC.restoreCurrent();$('pwaMessage').textContent='현재 릴리스 복원을 요청했습니다.'};$('checkUpdate').onclick=async()=>{const reg=await navigator.serviceWorker?.getRegistration();await reg?.update();$('pwaMessage').textContent='업데이트 확인을 요청했습니다.'};window.addEventListener('message',()=>{renderFoundation();renderApproval();renderCutover()});window.addEventListener('jk-performance-sample',renderFoundation)}
boot().catch(e=>{console.error(e);document.body.insertAdjacentHTML('beforeend',`<pre>${String(e.message||e)}</pre>`)})
})();
